const nonneg=v=>Number.isSafeInteger(v)&&v>=0;
class Orders {
  constructor(stock,prices={}) { this.stock={...stock};this.prices={...prices};this.rows={}; }
  reserve(id,sku,qty,now=0,ttl=10) {
    if(!Number.isSafeInteger(qty)||qty<=0) throw new RangeError('qty');
    if(!Number.isSafeInteger(ttl)||ttl<=0) throw new RangeError('ttl');
    if(!nonneg(now)) throw new RangeError('now');
    if(!Number.isSafeInteger(now+ttl)) throw new RangeError('deadline');
    this.expire(now);
    const r=this.rows[id];
    if(r) return !r.expired&&r.sku===sku&&r.qty===qty;
    if((this.stock[sku]||0)<qty) return false;
    this.stock[sku]=(this.stock[sku]||0)-qty;
    this.rows[id]={sku,qty,deadline:now+ttl,expired:false};return true;
  }
  expire(now) {
    if(!nonneg(now)) throw new RangeError('now');
    for(const r of Object.values(this.rows)) {
      if(!r.expired&&r.deadline<=now) {r.expired=true;this.stock[r.sku]=(this.stock[r.sku]||0)+r.qty;}
    }
  }
  available(sku,now) {
    if(now!==undefined) this.expire(now);
    return this.stock[sku]||0;
  }
}
module.exports={Orders};
